import Foundation

public struct CapturePolicy: Sendable {
    public static let ownedType = "com.mediapublishing.ClipCopy.owned"
    public static let forbiddenTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
        "Pasteboard generator type", ownedType
    ]
    public static let mandatoryIDs: Set<String> = [
        "com.1password.1password", "com.agilebits.onepassword7", "com.bitwarden.desktop",
        "org.keepassxc.keepassxc", "com.apple.Passwords"
    ]
    private let excludedIDs: Set<String>
    private let excludedNames: Set<String>
    public init(excludedBundleIDs: [String] = [], excludedNames: [String] = []) {
        excludedIDs = Set((excludedBundleIDs + Array(Self.mandatoryIDs)).map { $0.lowercased() })
        self.excludedNames = Set((excludedNames + ["1Password", "Bitwarden", "KeePassXC", "Passwords", "Passwörter"]).map { $0.lowercased() })
    }

    public func readAllowedText(types: Set<String>, sourceBundleID: String?, activeBundleID: String?, activeAppName: String?,
                                numberOfItems: Int, paused: Bool, locked: Bool, readText: () -> String?) -> String? {
        guard !paused, !locked, numberOfItems == 1, types.isDisjoint(with: Self.forbiddenTypes),
              !types.isDisjoint(with: ["public.utf8-plain-text", "public.plain-text", "NSStringPboardType"]),
              let active = activeBundleID, !active.isEmpty, !excludedIDs.contains(active.lowercased()),
              !excludedNames.contains((activeAppName ?? "").lowercased()) else { return nil }
        if let source = sourceBundleID {
            guard !source.isEmpty, !excludedIDs.contains(source.lowercased()) else { return nil }
        }
        guard let text = readText(), !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
        return text
    }
}
